query Query($where: InventoryWhereInput) {
  inventory(where: $where) {
    edges {
      node {
        id
				active
        barcode
        number
        trackingNumber
        locationId
        productId
        productStrategyProcessId
        lotId
        locationId
        workOrderProcessId


        inventoryStatus {
          id
          name
          active
          suspect
          containment
          productionLoaded
        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight

        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            containment
          }
        }
      }
    }
  }
}

