(
  $R := $state.context.REQUEST.DATA;
  $L := $state.context.LOCAL;
  $sinv := $L.inventory[id=$R.sourceInventoryId];
  $dinv := $L.inventory[id=$R.destinationInventoryId];
  $w := $sinv.theoreticalWeight*($R.qty/$dinv.quantity.value)

  {
    "payloadU": [{
      "update": $sinv.{
        "quantity": {
          "value": quantity.value - $R.qty,
          "unitId": quantity.unitId
        },
        "active": quantity.value - $R.qty > 0,
        "theoreticalWeight": $isNilOrEmpty(theoreticalWeight) ? 0 : theoreticalWeight-$w,
        "netWeight": $isNilOrEmpty(netWeight) ? 0 : netWeight-$w,
        "grossWeight": $isNilOrEmpty(grossWeight) ? 0 : grossWeight - $w
      }
    },{
      "update": $dinv.{
        "quantity": {
          "value": quantity.value + $R.qty,
          "unitId": quantity.unitId
        },
        "active": quantity.value + $R.qty > 0,
        "theoreticalWeight": $isNilOrEmpty(theoreticalWeight) ? 0 : theoreticalWeight+$w,
        "netWeight": $isNilOrEmpty(netWeight) ? 0 : netWeight+$w,
        "grossWeight": $isNilOrEmpty(grossWeight) ? 0 : grossWeight+$w
      }
    }],
    "payloadT": {
        "create": $dinv.{
          "sourceQuantity": {
             "value": $R.qty,
            "unitId": quantity.unitId
          },
          "destinationQuantity": {
            "value": quantity.value + $R.qty,
            "unitId": quantity.unitId
          },
          "sourceInventoryId":$sinv.id,
          "customData": $state.context.CLAIMS ? $state.context.CLAIMS : $state.claims,
          "destinationInventoryId":id,
          "sourceLocationId": locationId,
          "destinationLocationId": locationId,
          "sourceInventoryStatusId": inventoryStatus.id,
          "destinationInventoryStatusId": inventoryStatus.id,
          "sourceLotId": $sinv.lotId,
          "destinationLotId": lotId,
          "sourceProductId":productId,
          "destinationProductId":productId,
          "sourceProductStrategyProcessId":productStrategyProcessId,
          "destinationProductStrategyProcessId":productStrategyProcessId,
          "sourceWorkOrderProcessId": $sinv.workOrderProcessId,
          "destinationWorkOrderProcessId": workOrderProcessId,
          "sourceMasterInventoryId":$sinv.masterInventory.id,
          "destinationMasterInventoryId":masterInventory.id,
          "statusId":$coalesce([$state.context.REQUEST.DATA.statusId,$state.context.DEFAULT.statusId]),
          "adjustmentCodeId": $coalesce([$state.context.REQUEST.DATA.adjustmentCodeId,$state.context.DEFAULT.adjustmentCodeId]),
          "transactionTypeId": "Inventory Merge"
        }
    }
  }
)

